    'respuesta_completa' => '<p>Es frecuente que la ART otorgue el alta mientras el trabajador está bajo tratamiento farmacológico. La ART entiende que la medicación es parte del mantenimiento y que la evolución de la lesión ya no va a mejorar significativamente. Si quedaron limitaciones, te corresponden porcentajes de incapacidad. El alta no corta el tratamiento médico, que debe seguir cubierto por la ART.</p><p>Lo fundamental es no confundir el alta con curarte. Si tenés secuelas, reclamá tu incapacidad. Un abogado puede ayudarte a determinar si el alta fue otorgado correctamente.</p>',
