    'respuesta_completa' => '<p>La estabilidad médica es un concepto clave en el sistema de ART. Significa que tu cuadro clínico llegó a un punto de equilibrio donde no hay mejoría significativa esperada y no hay empeoramiento. Recién en este punto se determina el porcentaje de incapacidad. La ART puede declarar la estabilidad médica de oficio o después de evaluarte. Si no estás de acuerdo, podés pedir una revisión ante la Comisión Médica.</p><p>La estabilidad médica no es lo mismo que estar curado: podés tener secuelas permanentes que generen derecho a una indemnización.</p>',
