    'respuesta_corta' => 'No, es considerado despido discriminatorio. La ley protege a los trabajadores con accidente de trabajo.',
    'respuesta_completa' => '<p>El despido después del alta puede ser discriminatorio. Si te despiden por el accidente, es nulo. Podés reclamar la reinstalación o una indemnización agravada. Documentá todo y consultá con un abogado.</p>',
