    'respuesta_corta' => 'Podés impugnar el porcentaje ante la Comisión Médica dentro de los 5 días hábiles.',
    'respuesta_completa' => '<p>Si el porcentaje no te parece justo, impugná ante la Comisión Médica en 5 días hábiles. La Comisión designará un perito independiente. No aceptes un porcentaje bajo sin consultar con un abogado.</p>',
