    'respuesta_corta' => 'Sí, la ART debe notificarte formalmente. Sin notificación, el alta no tiene efectos.',
    'respuesta_completa' => '<p>La notificación del alta es obligatoria. La ART debe notificarte por escrito. Recién después empieza a correr el plazo de 10 días para impugnar. Guardá toda la documentación.</p>',
