    'respuesta_corta' => 'Si se descubre una lesión nueva relacionada con el accidente, la ART debe reabrir tu caso.',
    'respuesta_completa' => '<p>Si después del alta se descubre una lesión no diagnosticada relacionada con el accidente, la ART debe cubrirla. Solicitá la reapertura ante la Comisión Médica. Documentá bien el diagnóstico nuevo.</p>',
