    'respuesta_corta' => 'No, si la depresión es consecuencia del accidente, la ART debe tratarla. No pueden darte el alta sin estabilizarte.',
    'respuesta_completa' => '<p>La depresión derivada del accidente es cubierta por la ART. Debe cubrir tratamiento psicológico y psiquiátrico. No se puede determinar la estabilidad sin estabilizar el cuadro depresivo. Si te dan el alta, impugnalo.</p>',
