    'respuesta_corta' => 'Si la indemnización no te parece suficiente, podés reclamar ante la Comisión Médica o la justicia.',
    'respuesta_completa' => '<p>Si la indemnización no te parece justa, reclamá ante la Comisión Médica. Si no te da resultado, podés ir a la justicia. No aceptes un monto bajo sin consultar con un abogado.</p>',
