    'respuesta_completa' => '<p>Si tu estado empeoró después del alta, solicitá ante la Comisión Médica que reevalúen tu caso. Presentá informes médicos que demuestren el empeoramiento. Si está relacionado con el accidente, tu caso puede ser reaperturado.</p>',
