    'respuesta_corta' => 'Primero buscá atención médica, después avisá a tu empleador y guardá todos los certificados.',
    'respuesta_completa' => '<p>Si sufrís un accidente en el trabajo, buscá atención médica inmediata, avisá a tu empleador, guardá los certificados y denunciá el accidente ante la ART. La ART está obligada a cubrir el tratamiento y pagarte una prestación económica.</p>',
