    'respuesta_corta' => 'No hay plazo máximo, pero denunciá lo antes posible. Tu empleador debe denunciar en 48 horas.',
    'respuesta_completa' => '<p>La ley no establece un plazo máximo, pero es crucial hacerlo pronto. Tu empleador debe denunciar en 48 horas. Si no lo hace, hacelo vos directamente ante la ART. No esperes.</p>',
