    'respuesta_corta' => 'Puede intentar, pero con pruebas podés apelar ante la Comisión Médica o la justicia.',
    'respuesta_completa' => '<p>Si la ART rechaza tu denuncia, reuní pruebas (testigos, fotos, certificados). Presentá el reclamo ante la Comisión Médica. Si no te da resultado, andá a la justicia federal. No te des por vencido.</p>',
