    'respuesta_corta' => 'Es la prestación mientras estás imposibilitado. Se calcula sobre el 100% de tu ingreso base.',
    'respuesta_completa' => '<p>La incapacidad temporal equivale al 100% de tu ingreso base. Los primeros 10 días los paga tu empleador, y después los asume la ART. Si te pagan de menos, reclamá ante la Comisión Médica.</p>',
