    ],
[
        'id' => 'art-002',
        'categoria' => 'ART',
        'pregunta' => '¿Cómo hago para denunciar un accidente ante la ART?',
        'respuesta_corta' => 'Tenés que avisar a tu empleador de inmediato y exigir que denuncie el siniestro ante la ART. También podés hacerlo vos directamente.',
        'respuesta_completa' => 'Para denunciar un accidente de trabajo ante la ART, primero avisale a tu empleador de inmediato. El empleador tiene la obligación legal de denunciar el siniestro ante la ART dentro de las 48 horas. Si el empleador no lo hace, vos podés presentar la denuncia directamente ante la ART. Necesitás llevar tu DNI, una descripción del accidente, y si es posible, datos del testigo. La ART tiene la obligación de recibir tu denuncia y abrir una carpeta. A partir de ahí, te van a asignar un médico y van a iniciar las prestaciones. Si la ART rechaza tu denuncia, podés apelar ante la Comisión Médica Jurisdiccional.',
        'definiciones_relacionadas' => ['denuncia', 'siniestro', 'plazo'],
        'lesiones_relacionadas' => ['hombro', 'rodilla', 'mano'],
        'articulos_relacionados' => ['accidentes-de-trabajo', 'que-hacer'],
