[
        'id' => 'art-003',
        'categoria' => 'ART',
        'pregunta' => '¿Qué cubre la ART en caso de accidente?',
        'respuesta_corta' => 'La ART cubre asistencia médica completa, indemnización por incapacidad, gastos de sepelio si hay fallecimiento, y reintegro de gastos por traslado y medicamentos.',
        'respuesta_completa' => 'La ART está obligada a cubrir una amplia gama de prestaciones cuando sufrís un accidente de trabajo. Entre las principales prestaciones se encuentran: asistencia médica, quirúrgica, farmacéutica y hospitalaria; rehabilitación kinesiológica y psicológica; prótesis y ayudas técnicas; reintegro de gastos de traslado; indemnización por incapacidad permanente o temporaria; subsidio diario por incapacidad temporaria; y capacitación para trabajadores con incapacidad permanente. La ART no puede limitar las prestaciones sin justificación médica.',
        'definiciones_relacionadas' => ['prestaciones', 'cobertura', 'asistencia-medica'],
        'lesiones_relacionadas' => ['hombro', 'columna', 'rodilla'],
