[
        'id' => 'art-004',
        'categoria' => 'ART',
        'pregunta' => '¿La ART me puede rechazar la denuncia del accidente?',
        'respuesta_corta' => 'Sí, la ART puede rechazar la denuncia si considera que no fue un accidente de trabajo. Pero vos podés apelar esa decisión.',
        'respuesta_completa' => 'La ART tiene derecho a evaluar si el siniestro fue realmente un accidente de trabajo. Sin embargo, no puede rechazar la denuncia sin una fundamentación clara. Si la ART te rechaza la denuncia, podés apelar ante la Comisión Médica Jurisdiccional o iniciar una acción judicial ante la justicia del trabajo. Es fundamental que reúnas toda la documentación posible: partes de accidente, constancias médicas, testimonios de compañeros, y cualquier otra prueba. La ART no puede rechazar la denuncia sin fundamentar su decisión.',
        'definiciones_relacionadas' => ['rechazo', 'apelacion', 'comision-medica'],
