        'respuesta_corta' => 'Si la ART no te brinda el tratamiento adecuado, podés reclamar ante la Comisión Médica Jurisdiccional o buscar asesoramiento legal.',
        'respuesta_completa' => 'Si la ART no te brinda el tratamiento médico que necesitás, tenés varias opciones. Primero, reclamale por escrito, exigiendo la atención médica que te corresponde. Si no responden, podés presentar un reclamo ante la Comisión Médica Jurisdiccional, que tiene la facultad de ordenar a la ART que te brinde el tratamiento. También podés iniciar una acción judicial ante la justicia del trabajo. Es importante que documentes todo: guardá los resultados de los estudios, las recetas, y cualquier comunicación con la ART.',
