        'respuesta_corta' => 'No hay plazo fijo para denunciar, pero se recomienda hacerlo lo antes posible. La acción prescribe a los 2 años.',
        'respuesta_completa' => 'No existe un plazo legal exacto para denunciar un accidente de trabajo ante la ART. Se recomienda hacerlo lo antes posible, idealmente dentro de las primeras 48 horas. Sin embargo, se recomienda hacerlo lo antes posible, idealmente dentro de las primeras 48 horas. Si tu empleador no denuncia el siniestro, vos podés hacerlo directamente ante la ART. En casos de enfermedades profesionales que se manifiestan gradualmente, el plazo se computa desde que el trabajador tiene conocimiento de la enfermedad y su relación con el trabajo.',
