[
        'id' => 'art-007',
        'categoria' => 'ART',
        'pregunta' => '¿Qué es un accidente de trabajo según la LRT?',
        'respuesta_corta' => 'Un accidente de trabajo es todo acontecimiento súbito y violento que ocurre en ocasión o como consecuencia del trabajo.',
        'respuesta_completa' => 'Según la Ley de Riesgos del Trabajo, accidente de trabajo es todo acontecimiento súbito y violento, producido en ocasión o como consecuencia del trabajo que ejecuta un empleado. Esto incluye los accidentes que ocurren en el lugar de trabajo, pero también los que suceden yendo o volviendo del mismo (accidente in itinere). Para que sea considerado accidente de trabajo, el siniestro debe tener relación directa con la actividad laboral, aunque no necesariamente debe ocurrir en las instalaciones de la empresa.',
        'definiciones_relacionadas' => ['accidente-de-trabajo', 'lrt', 'nexo-causal'],
