        'pregunta' => '¿La ART me cubre si me accidenté yendo al trabajo?',
        'respuesta_corta' => 'Sí, si te accidentaste yendo o volviendo del trabajo, se considera accidente in itinere y la ART está obligada a cubrirte.',
        'respuesta_completa' => 'El accidente in itinere es aquel que sufre el trabajador durante el trayecto entre su domicilio y su lugar de trabajo. La ART está obligada a cubrir estos accidentes siempre que se demuestre que el recorrido era el habitual. Para que sea considerado accidente in itinere, debe existir un nexo causal directo entre el trayecto laboral y el siniestro. Si te desviás considerablemente de tu recorrido habitual, la ART podría cuestionar la cobertura.',
