        'articulos_relacionados' => ['accidentes-de-trabajo', 'que-hacer'],
    ],
[
        'id' => 'art-009',
        'categoria' => 'ART',
        'pregunta' => '¿Qué es una enfermedad profesional según la ART?',
        'respuesta_corta' => 'Una enfermedad profesional es aquella que surge como consecuencia del tipo de trabajo que realizás o por los agentes a los que estás expuesto.',
        'respuesta_completa' => 'La enfermedad profesional es aquella enfermedad que contrae el trabajador como consecuencia del trabajo que realiza. Se considera enfermedad profesional cuando existe una relación directa entre la enfermedad y las condiciones o riesgos del trabajo. Por ejemplo, la tendinitis en el hombro por movimientos repetitivos, la hernia discal lumbar por carga de pesos, o la sordera por exposición a ruidos intensos. La ART debe cubrir las enfermedades profesionales de la misma manera que cubre los accidentes de trabajo.',
        'definiciones_relacionadas' => ['enfermedad-profesional', 'nexo-causal', 'condiciones-laborales'],
