        'respuesta_completa' => 'La ley protege a los trabajadores que sufren accidentes de trabajo. Tu empleador no puede despedirte por haber sufrido un accidente laboral. Si lo hace, ese despido se considera sin causa y te corresponden todas las indemnizaciones: antigüedad, preaviso, SAC proporcional, e indemnización por daños y perjuicios. Si ya te despidieron injustamente, presentá una denuncia ante la justicia del trabajo. Guardá todas las pruebas: comunicaciones con tu empleador, partes de accidente, constancias médicas.',
