        'respuesta_completa' => 'La Comisión Médica Jurisdiccional es un organismo administrativo independiente que funciona en cada jurisdicción. Su función principal es resolver los conflictos entre trabajadores y ART respecto a las prestaciones médicas y la determinación de la incapacidad. Está integrada por médicos especialistas que realizan una evaluación objetiva del trabajador. Su decisión tiene carácter obligatorio para ambas partes, aunque puede ser apelada ante la justicia. El trámite es gratuito y no requiere abogado.',
