        'respuesta_completa' => 'El subsidio por incapacidad temporaria equivale al 100% de tu ingreso base. Los primeros 10 días los paga tu empleador, y después los asume la ART hasta el Alta Médica o la determinación de incapacidad permanente. El subsidio se calcula sobre tu salario registrado, incluyendo todos los conceptos remunerativos. La ART tiene la obligación de pagarte puntualmente este subsidio. No puede ser menor al salario mínimo vital y móvil.',
