        'respuesta_completa' => 'Cuando un empleador no contrata ART, incurre en una falta grave que lo hace responsable directo de todas las prestaciones que la ART debería haber brindado. Debe hacerte cargo de todos los gastos médicos e indemnizaciones. Además, puede ser sancionado administrativamente con multas y hasta con la clausura del establecimiento. Denunciá la situación ante la ART de la Superintendencia de Riesgos del Trabajo y ante la justicia del trabajo.',
