        'respuesta_completa' => 'La ART tiene la obligación de brindarte asistencia médica a través de su red de prestadores. Si no estás conforme con el médico asignado, podés solicitar un cambio a la ART. Si la ART no te da una respuesta satisfactoria, podés recurrir a la Comisión Médica Jurisdiccional. No conformes con una atención médica que no te satisfaga.',
