        'respuesta_corta' => 'Una enfermedad de trabajo es aquella que se origina por las condiciones en que trabajás, como la tendinitis por movimientos repetitivos.',
        'respuesta_completa' => 'Las enfermedades de trabajo son aquellas que contrae el trabajador como consecuencia directa de su actividad laboral. Se diferencian de las enfermedades comunes porque existe una relación causal clara. Algunos ejemplos son: tendinitis de hombro o muñeca por movimientos repetitivos, hernia discal lumbar por carga de pesos, síndrome del túnel carpiano, sordera por ruidos, o enfermedades respiratorias por sustancias tóxicas. La ART debe cubrir estas enfermedades igual que los accidentes de trabajo.',
