        'respuesta_completa' => 'La Superintendencia de Riesgos del Trabajo (SRT) es el organismo público encargado de controlar y regular el funcionamiento de las ART. Supervisa que las ART brinden adecuadamente las prestaciones médicas y económicas, investiga denuncias, y puede imponer sanciones. Si tenés un problema con tu ART, podés presentar una denuncia ante la SRT o comunicarte para obtener información sobre tus derechos.',
