        'respuesta_completa' => 'La contingencia profesional engloba todas las situaciones que pueden afectar la salud y capacidad laboral de un trabajador como consecuencia de su actividad profesional. Esto incluye los accidentes de trabajo y las enfermedades profesionales cubiertos por la LRT. Cuando un trabajador sufre una contingencia profesional, la ART está obligada a brindarle las prestaciones correspondientes. No confundir con contingencias comunes no relacionadas con el trabajo.',
