        'respuesta_completa' => 'Si la ART no te paga el subsidio por incapacidad temporaria, comunicate por escrito exigiendo el pago. Si no responde, presentá un reclamo ante la Comisión Médica Jurisdiccional, que puede ordenar a la ART que te pague. También podés iniciar una acción judicial. El subsidio equivale al 100% de tu ingreso base desde el primer día de incapacidad hasta el Alta Médica.',
