        'respuesta_completa' => 'La protección al trabajador accidentado es un conjunto de medidas que la ley establece para proteger a los trabajadores que sufren accidentes de trabajo. Implica que el empleador no puede despedirte, reducirte el sueldo, o discriminarte por haber sufrido un accidente laboral. Si tu empleador lo hace, el despido se considera nulo y te corresponden todas las indemnizaciones. Esta protección se extiende durante todo el periodo de tratamiento y recuperación.',
