        'respuesta_completa' => 'La indemnización por incapacidad permanente se calcula con esta fórmula: 53 × Ingreso Base Mensual (RIPTE) × % de Incapacidad × (65 / Edad). El 53 es el número que establece la ley, el Ingreso Base es tu salario promedio registrado, el porcentaje lo fija el baremo según tu lesión, y el coeficiente (65/ edad) reduce el monto cuanto mayor seas. También existe un piso mínimo establecido por la SRT que la ART nunca puede pagar menos. Si tenés dudas, usá nuestra calculadora.',
