        'respuesta_completa' => 'El capital de pérdida de capacidad productiva es la indemnización que la ART te paga cuando quedás con una incapacidad permanente que disminuye tu capacidad para generar ingresos. Se calcula con la fórmula de ley: 53 × Ingreso Base Mensual (RIPTE) × % de Incapacidad × (65 / Edad). Existe un piso mínimo (Resolución SRT) y un tope de 75 salarios mínimos vitales y móviles. Consultá nuestra calculadora para un estimado.',
