        'respuesta_completa' => 'La indemnización por incapacidad del 10% se calcula con la fórmula de ley: 53 × Ingreso Base (RIPTE) × 10% × (65 / Edad). Por ejemplo, si tenés 40 años y tu Ingreso Base es de $800.000: 53 × $800.000 × 10% × (65/40) = $689.000 (aprox.). El resultado puede ser mayor al piso mínimo o menor al tope de 75 SMVM. Usá nuestra calculadora para un estimado.',
