        'respuesta_completa' => 'El daño moral es una indemnización adicional por el sufrimiento físico o psicológico significativo a causa del accidente. Aunque la LRT no lo contempla expresamente, la jurisprudencia ha reconocido su existencia. Se reclama ante la justicia del trabajo cuando el accidente causó dolor severo, limitación importante o impacto en la calidad de vida. Consultá con un abogado.',
