        'respuesta_completa' => 'La estabilidad médica es el momento en que tu cuadro clínico se ha estabilizado y ya no va a mejorar significativamente con más tratamientos. Es en ese momento cuando la ART determina tu incapacidad permanente y te da el Alta Médica. Si no estás de acuerdo con la estabilidad médica declarada, podés apelar ante la Comisión Médica.',
