        'respuesta_completa' => 'La tabla de factores de incapacidad de la LRT establece un porcentaje para cada tipo de lesión contemplada. Estos porcentajes se usan para calcular la indemnización multiplicándolos por la edad y el salario del trabajador. La tabla es taxativa pero la jurisprudencia ha admitido que lesiones no contempladas puedan ser indemnizadas. Consultá la tabla en nuestro sitio para ver los porcentajes específicos.',
