        'respuesta_completa' => '<p><em>Nota: Los porcentajes de incapacidad que se mencionan a continuación son ejemplos orientativos. Desde el 1 de febrero de 2026 rige el nuevo baremo (Decreto 549/2025) con porcentajes diferentes. Consultá la tabla de baremo actualizada en nuestro sitio o usá la calculadora para un estimado.</em></p><p>La ART cubre: <strong>rotura del manguito rotador</strong>, <strong>tendinitis</strong> por esfuerzo, <strong>luxaciones</strong> por caídas, <strong>bursitis</strong> por presión constante, <strong>fracturas</strong> y <strong>síndrome de pinzamiento</strong>. Si tu lesión fue en el trabajo, la ART debe cubrirla.</p>',
